  vad;
  frameMs;
  maxPreRollFrames;
  silenceEndFrames;
  minSpeechFrames;
  maxSegmentFrames;
  preRoll = [];
  collecting = false;
  collected = [];
  recentVoiced = [];
  silenceRun = 0;
  voicedFrames = 0;
