function voiceCoachKey({ mode, status, pending, isProcessing }) {
  if (mode === "off")
    return null;
  switch (status) {
    case "dormant":
      return "voice.coach.dormant";
    case "speaking":
      return "voice.coach.speaking";
    case "announced":
      if (mode === "ask_first")
        return pending ? "voice.coach.goAheadPending" : "voice.coach.goAheadResult";
      break;
    case "listening":
      if (pending === "question")
        return "voice.coach.listeningQuestion";
      if (pending === "confirmation")
        return "voice.coach.listeningDecision";
      return "voice.coach.listening";
    case "idle":
    case "transcribing":
      break;
  }
  return isProcessing ? "voice.coach.idleWorking" : "voice.coach.idle";
}

